                PaintChannel::Fill => shape.fill_paint = Some(index),
                PaintChannel::Stroke => shape.stroke_paint = Some(index),
            }
            builder.finalize_shape(draft, p.shape, shape, control)?;
            Ok((id, index))
        })();
        if result.is_err() {
            mark.epoch = builder.scenes[i].epoch;
            builder.rollback_internal(mark)?;
            // Output may not yet have transferred. Clean it unconditionally.
            if job.slice(output.pixels).is_ok() {
                job.release(output.pixels)?;
            }
        }
        self.pending = None;
        result
    }
}
use crate::types::{invalid, limit, stopped};
use crate::*;
use std::sync::atomic::{AtomicU64, Ordering};
static NEXT_OWNER: AtomicU64 = AtomicU64::new(1);
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PatternTicket {
    owner: u64,
    serial: u64,
}
#[derive(Debug)]
pub(crate) struct Pending {
    pub(crate) ticket: PatternTicket,
    pub(crate) descriptor: PatternDescriptor,
    pub(crate) scene: SceneId,
    pub(crate) production: Option<crate::pattern_publication::PatternContinuation>,
}
/// One outstanding nested pattern at the current traversal suspension point.
/// Wrong/stale tickets and failed completions never advance that continuation.
#[derive(Debug)]
pub struct PatternTickets {
    owner: u64,
    next: u64,
    pub(crate) pending: Option<Pending>,
}
impl PatternTickets {
    pub fn new() -> Result<Self> {
        let owner = NEXT_OWNER
            .try_update(Ordering::Relaxed, Ordering::Relaxed, |x| x.checked_add(1))
            .map_err(|_| crate::memory::arithmetic())?;
        Ok(Self {
            owner,
            next: 1,
            pending: None,
        })
    }
    pub fn request<'a, V: ViewportRead, A: Copy>(
        &mut self,
        child: SceneView<'a, V, A>,
        descriptor: PatternDescriptor,
        control: &mut dyn WorkControl,
    ) -> Result<PatternRequest<'a, V, A>> {
        control.checkpoint().map_err(stopped)?;
        if self.pending.is_some() {
            return Err(invalid(descriptor.error_offset));
        }
        if child.scene(child.id).is_none() {
            return Err(invalid(descriptor.error_offset));
        }
        if descriptor.width == 0
            || descriptor.height == 0
            || descriptor.width > 4096
            || descriptor.height > 4096
            || (descriptor.width as usize) * (descriptor.height as usize) > 1_048_576
        {
            return Err(limit(LimitKind::Patterns));
        }
        if !descriptor.tile_width.is_finite()
            || !descriptor.tile_height.is_finite()
            || descriptor.tile_width <= 0.0
            || descriptor.tile_height <= 0.0
            || !vexel_geometry::affine_valid(descriptor.content_transform)
        {
            return Err(invalid(descriptor.error_offset));
        }
        let ticket = PatternTicket {
            owner: self.owner,
            serial: self.next,
        };
        self.next = self
            .next
            .checked_add(1)
            .ok_or_else(crate::memory::arithmetic)?;
        self.pending = Some(Pending {
            ticket,
            descriptor,
            scene: child.id,
            production: None,
        });
        Ok(PatternRequest {
            ticket,
            child,
            definition: descriptor.definition,
            width: descriptor.width,
            height: descriptor.height,
            tile_width: descriptor.tile_width,
            tile_height: descriptor.tile_height,
            content_transform: descriptor.content_transform,
            error_offset: descriptor.error_offset,
        })
    }
    pub fn complete(
        &mut self,
        ticket: PatternTicket,
        tile: vexel_raster::Tile,
        control: &mut dyn WorkControl,
    ) -> Result<(SceneId, Pattern)> {
        control.checkpoint().map_err(stopped)?;
        let pending = self.pending.as_ref().ok_or_else(|| invalid(0))?;
        if pending.production.is_some() || pending.ticket != ticket
            || tile.width() != pending.descriptor.width
            || tile.height() != pending.descriptor.height
        {
            return Err(invalid(pending.descriptor.error_offset));
        }
        if tile.allocated_byte_count() > 16 * 1024 * 1024 {
            return Err(limit(LimitKind::Patterns));
        }
        let p = self.pending.take().ok_or_else(|| invalid(0))?;
        Ok((
            p.scene,
            Pattern {
                tile,
                definition: p.descriptor.definition,
                tile_width: p.descriptor.tile_width,
                tile_height: p.descriptor.tile_height,
                content_transform: p.descriptor.content_transform,
            },
        ))
    }
    pub fn cancel(&mut self) {
        self.pending = None;
    }
    pub fn outstanding(&self) -> bool {
        self.pending.is_some()
    }
}
//! Copy-on-change evaluated tables. The immutable scene/source remains borrowed;
//! memory statistics below describe additional owned frame storage only.
use crate::memory::{add, arithmetic, bytes};
use crate::types::{invalid, limit, stopped};
use crate::*;
#[derive(Debug)]
pub struct EvaluatedFrame<'a> {
    base: SceneView<'a>,
    byte_limit: usize,
    edges: Option<Vec<Edge>>,
    colors: Option<Vec<[u8; 4]>>,
    shapes: Option<Vec<Shape>>,
    fill_paints: Option<Vec<Paint>>,
    stroke_paints: Option<Vec<Paint>>,
    transforms: Option<Vec<TransformFrame>>,
    clips: Option<Vec<Clip>>,
    stats: MemoryStats,
}
#[derive(Debug)]
pub struct FrameBuilder<'a> {
    frame: EvaluatedFrame<'a>,
    byte_limit: usize,
}
impl<'a> EvaluatedFrame<'a> {
    pub fn view(&self) -> SceneView<'_> {
        self.base.overlay(
            self.edges.as_deref(),
            self.colors.as_deref(),
            self.shapes.as_deref(),
            self.fill_paints.as_deref(),
            self.stroke_paints.as_deref(),
            self.transforms.as_deref(),
            self.clips.as_deref(),
        )
    }
    pub fn base(&self) -> SceneView<'a> {
        self.base
    }
    pub fn memory_stats(&self) -> MemoryStats {
        self.stats
    }
    /// Publish a complete clip update only after validating every replacement.
    /// Old owned clips remain live during validation and admission; the original
    /// configured frame budget includes that overlap. Base data never changes.
    pub fn replace_clips(
        &mut self,
        values: Vec<Clip>,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        control.checkpoint().map_err(stopped)?;
        if values.len() != self.base.clips.len() {
            return Err(invalid(0));
        }
        let view = self.view();
        for (index, clip) in values.iter().enumerate() {
            control.charge(WorkKind::ClipChild, 1).map_err(stopped)?;
            if clip.parent != self.base.clips[index].parent {
                return Err(invalid(0));
            }
            crate::validate::clip_view(view, clip, control)?;
        }
        let new = clip_bytes(&values, control)?;
        if new > 64 * 1024 * 1024 {
            return Err(limit(LimitKind::Animation));
        }
        let old = if let Some(clips) = &self.clips {
            clip_bytes(clips, control)?
        } else {
            0
        };
        let overlap = add(self.stats.live_bytes, new)?;
        if overlap > self.byte_limit {
            return Err(limit(LimitKind::ReservedBytes));
        }
        let live = add(
            self.stats
                .live_bytes
                .checked_sub(old)
                .ok_or_else(arithmetic)?,
            new,
        )?;
        let history = add(self.stats.total_allocated_bytes, new)?;
        let allocations = self
            .stats
            .allocation_count
            .checked_add(usize::from(new != 0))
            .ok_or_else(arithmetic)?;
        control.checkpoint().map_err(stopped)?;
        self.clips = Some(values);
        self.stats.live_bytes = live;
        self.stats.peak_live_bytes = self.stats.peak_live_bytes.max(overlap);
        self.stats.total_allocated_bytes = history;
        self.stats.allocation_count = allocations;
        Ok(())
    }
}
impl<'a> FrameBuilder<'a> {
    pub fn new(base: SceneView<'a>, byte_limit: usize) -> Result<Self> {
        if base.scene(base.id).is_none() {
            return Err(invalid(0));
        }
        Ok(Self {
            frame: EvaluatedFrame {
                base,
                byte_limit,
                edges: None,
                colors: None,
                shapes: None,
                fill_paints: None,
                stroke_paints: None,
                transforms: None,
                clips: None,
                stats: Default::default(),
            },
            byte_limit,
        })
    }
    fn incoming(&mut self, new: usize, old: usize) -> Result<()> {
        let peak = add(self.frame.stats.live_bytes, new)?;
        if peak > self.byte_limit {
            return Err(limit(LimitKind::ReservedBytes));
        }
        let live = add(self.frame.stats.live_bytes - old, new)?;
        let history = add(self.frame.stats.total_allocated_bytes, new)?;
        let count = self
            .frame
            .stats
            .allocation_count
            .checked_add(usize::from(new != 0))
            .ok_or_else(arithmetic)?;
        self.frame.stats.live_bytes = live;
        self.frame.stats.peak_live_bytes = self.frame.stats.peak_live_bytes.max(peak);
        self.frame.stats.total_allocated_bytes = history;
        self.frame.stats.allocation_count = count;
        Ok(())
    }
    fn copy<T: Copy>(&mut self, source: &[T], control: &mut dyn WorkControl) -> Result<Vec<T>> {
        control.checkpoint().map_err(stopped)?;
        let requested = source
            .len()
            .checked_mul(std::mem::size_of::<T>())
            .ok_or_else(arithmetic)?;
        if add(self.frame.stats.live_bytes, requested)? > self.byte_limit {
            return Err(limit(LimitKind::ReservedBytes));
        }
        let mut values = Vec::new();
        values
            .try_reserve_exact(source.len())
            .map_err(|_| Diagnostic {
                kind: ErrorKind::OutOfMemory,
                offset: 0,
            })?;
        let actual = bytes(&values)?;
        self.incoming(actual, 0)?;
        for item in source {
            if let Err(stop) = control.charge(WorkKind::AnimationTransform, 1) {
                self.frame.stats.live_bytes -= actual;
                return Err(stopped(stop));
            }
            values.push(*item);
        }
        Ok(values)
    }
    pub fn replace_edges(
        &mut self,
        values: Vec<Edge>,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        control.checkpoint().map_err(stopped)?;
        if values.len() != self.frame.base.edges.len() {
            return Err(invalid(0));
        }
        for value in &values {
            control.charge(WorkKind::Edge, 1).map_err(stopped)?;
            if ![value.a.x, value.a.y, value.b.x, value.b.y]
                .into_iter()
                .all(|v| v.is_finite() && v.abs() <= 1e6)
            {
                return Err(invalid(0));
            }
        }
        let old = self
            .frame
            .edges
            .as_ref()
            .map(bytes)
            .transpose()?
            .unwrap_or(0);
        self.incoming(bytes(&values)?, old)?;
        self.frame.edges = Some(values);
        Ok(())
    }
    pub fn replace_colors(
        &mut self,
        values: Vec<[u8; 4]>,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        control.checkpoint().map_err(stopped)?;
        if values.len() != self.frame.base.edge_colors.len() {
            return Err(invalid(0));
        }
        let old = self
            .frame
            .colors
            .as_ref()
            .map(bytes)
            .transpose()?
            .unwrap_or(0);
        self.incoming(bytes(&values)?, old)?;
        self.frame.colors = Some(values);
        Ok(())
    }
    pub fn set_shape(
        &mut self,
        id: ShapeId,
        value: Shape,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        control.checkpoint().map_err(stopped)?;
        let old = self.frame.base.shape(id).ok_or_else(|| invalid(0))?;
        if old.edges != value.edges
            || old.subpaths != value.subpaths
            || old.source.element != value.source.element
        {
            return Err(invalid(0));
        }
        crate::validate::shape_attributes_view(self.frame.view(), &value, control)?;
        if self.frame.shapes.is_none() {
            self.frame.shapes = Some(self.copy(self.frame.base.shapes, control)?);
        }
        self.frame.shapes.as_mut().ok_or_else(|| invalid(0))?[id.index()] = value;
        Ok(())
    }
    pub fn set_transform(
        &mut self,
        id: TransformId,
        value: TransformFrame,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        control.checkpoint().map_err(stopped)?;
        let old = self.frame.base.transform(id).ok_or_else(|| invalid(0))?;
        if old.parent != value.parent
            || old.source_offset != value.source_offset
            || ![value.attribute, value.suffix, value.motion]
                .into_iter()
                .all(vexel_geometry::affine_valid)
        {
            return Err(invalid(0));
        }
        if self.frame.transforms.is_none() {
            self.frame.transforms = Some(self.copy(self.frame.base.transforms, control)?);
        }
        self.frame.transforms.as_mut().ok_or_else(|| invalid(0))?[id.index()] = value;
        Ok(())
    }
    pub fn set_fill_paint(
        &mut self,
        index: usize,
        value: Paint,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.set_paint(index, value, true, control)
    }
    pub fn set_stroke_paint(
        &mut self,
        index: usize,
        value: Paint,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.set_paint(index, value, false, control)
    }
    fn set_paint(
        &mut self,
        index: usize,
        value: Paint,
        fill: bool,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        control.checkpoint().map_err(stopped)?;
        let source = if fill {
            self.frame.base.fill_paints
        } else {
            self.frame.base.stroke_paints
        };
        if index >= source.len() {
            return Err(invalid(0));
        }
        crate::validate::paint_view(self.frame.view(), &value, control)?;
        if fill {
            if self.frame.fill_paints.is_none() {
                self.frame.fill_paints = Some(self.copy(source, control)?);
            }
            self.frame.fill_paints.as_mut().ok_or_else(|| invalid(0))?[index] = value;
        } else {
            if self.frame.stroke_paints.is_none() {
                self.frame.stroke_paints = Some(self.copy(source, control)?);
            }
            self.frame
                .stroke_paints
                .as_mut()
                .ok_or_else(|| invalid(0))?[index] = value;
        }
        Ok(())
    }
    pub fn set_clip(
        &mut self,
        id: ClipId,
        value: Clip,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        control.checkpoint().map_err(stopped)?;
        let original = self.frame.base.clip(id).ok_or_else(|| invalid(0))?;
        if original.parent != value.parent {
            return Err(invalid(0));
        }
        crate::validate::clip_view(self.frame.view(), &value, control)?;
        let new = add(
            bytes(&value.geometry.edges)?,
            bytes(&value.geometry.shapes)?,
        )?;
        if let Some(clips) = &self.frame.clips {
            let old = add(
                bytes(&clips[id.index()].geometry.edges)?,
                bytes(&clips[id.index()].geometry.shapes)?,
            )?;
            let size = clip_bytes(clips, control)?;
            if add(size - old, new)? > 64 * 1024 * 1024 {
                return Err(limit(LimitKind::Animation));
            }
            self.incoming(new, old)?;
            self.frame.clips.as_mut().ok_or_else(|| invalid(0))?[id.index()] = value;
            return Ok(());
        }
        let before = self.frame.stats.live_bytes;
        let result = self.copy_clips(id, value, new, control);
        match result {
            Ok(values) => {
                self.frame.clips = Some(values);
                Ok(())
            }
            Err(error) => {
                self.frame.stats.live_bytes = before;
                Err(error)
            }
        }
    }
    fn copy_clips(
        &mut self,
        id: ClipId,
        value: Clip,
        nested: usize,
        control: &mut dyn WorkControl,
    ) -> Result<Vec<Clip>> {
        let mut result = Vec::new();
        let count = self.frame.base.clips.len();
        let minimum = count
            .checked_mul(std::mem::size_of::<Clip>())
            .ok_or_else(arithmetic)?;
        if add(self.frame.stats.live_bytes, add(minimum, nested)?)? > self.byte_limit {
            return Err(limit(LimitKind::ReservedBytes));
        }
        result.try_reserve_exact(count).map_err(|_| Diagnostic {
            kind: ErrorKind::OutOfMemory,
            offset: 0,
        })?;
        self.incoming(add(bytes(&result)?, nested)?, 0)?;
        let mut replacement = Some(value);
        for (index, source) in self.frame.base.clips.iter().enumerate() {
            control.charge(WorkKind::ClipChild, 1).map_err(stopped)?;
            if index == id.index() {
                result.push(replacement.take().ok_or_else(|| invalid(0))?);
            } else {
                let edges = self.copy(&source.geometry.edges, control)?;
                let shapes = self.copy(&source.geometry.shapes, control)?;
                result.push(Clip {
                    geometry: ClipGeometry { edges, shapes },
                    parent: source.parent,
                    owner_node: source.owner_node,
                    owner_before_suffix: source.owner_before_suffix,
                    object_bounding_box: source.object_bounding_box,
                    bounds: source.bounds,
                    user_inverse: source.user_inverse,
                });
            }
        }
        if clip_bytes(&result, control)? > 64 * 1024 * 1024 {
            return Err(limit(LimitKind::Animation));
        }
        Ok(result)
    }
    pub fn finish(self, control: &mut dyn WorkControl) -> Result<EvaluatedFrame<'a>> {
        control.checkpoint().map_err(stopped)?;
        let view = self.frame.view();
        for shape in view.shapes {
            crate::validate::shape_attributes_view(view, shape, control)?;
        }
        for paint in view.fill_paints.iter().chain(view.stroke_paints) {
            crate::validate::paint_view(view, paint, control)?;
        }
        for clip in view.clips {
            crate::validate::clip_view(view, clip, control)?;
        }
        let measured = self.frame.owned_bytes(control)?;
        if measured != self.frame.stats.live_bytes {
            return Err(invalid(0));
        }
        Ok(self.frame)
    }
}
impl EvaluatedFrame<'_> {
    fn owned_bytes(&self, control: &mut dyn WorkControl) -> Result<usize> {
        let mut total = 0;
        macro_rules! include {
            ($field:ident) => {
                if let Some(values) = &self.$field {
                    total = add(total, bytes(values)?)?;
                }
            };
        }
        include!(edges);
        include!(colors);
        include!(shapes);
        include!(fill_paints);
        include!(stroke_paints);
        include!(transforms);
        include!(clips);
        if let Some(clips) = &self.clips {
            for clip in clips {
                control.charge(WorkKind::ClipChild, 1).map_err(stopped)?;
                total = add(
                    total,
                    add(bytes(&clip.geometry.edges)?, bytes(&clip.geometry.shapes)?)?,
                )?;
            }
        }
        Ok(total)
    }
}

fn clip_bytes(values: &Vec<Clip>, control: &mut dyn WorkControl) -> Result<usize> {
    let mut total = bytes(values)?;
    for clip in values {
        control.charge(WorkKind::ClipChild, 1).map_err(stopped)?;
        total = add(
            total,
            add(bytes(&clip.geometry.edges)?, bytes(&clip.geometry.shapes)?)?,
        )?;
    }
    Ok(total)
}

//! Explicit source-owned decode lifecycle. Traversal never receives a ready view.
use crate::memory::{add, arithmetic};
use crate::model::SceneData;
use crate::types::{invalid, limit, stopped};
use crate::*;
use std::sync::atomic::Ordering;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DecodeInitialization {
    /// Root traversal has not established a viewport or hidden disposition.
    Unresolved,
    /// Root viewport is validated; actual same-source animation is still absent.
    Traversing,
    /// Root display:none skipped viewport and descendants; animation is absent.
    Hidden,
    /// Empty hidden document with its actual same-source animation installed.
    HiddenFinalized,
    Finalized,
}
/// Failure returns the actual input owner unchanged; callers can retry or drop it.
#[derive(Debug)]
pub struct FinalizationError {
    pub diagnostic: Diagnostic,
    pub animation: OwnedAnimation,
}
/// No apparently completed empty animation exists during traversal.
#[derive(Debug)]
pub(crate) enum AnimationStorage { Pending, Parsed(OwnedAnimation) }
impl AnimationStorage {
    pub(crate) fn parsed(&self) -> Option<&OwnedAnimation> {
        match self { Self::Pending => None, Self::Parsed(value) => Some(value) }
    }
    pub(crate) fn into_parsed(self) -> Option<OwnedAnimation> {
        match self { Self::Pending => None, Self::Parsed(value) => Some(value) }
    }
    pub(crate) fn storage_bytes(&self) -> Option<usize> {
        self.parsed()?.storage_bytes()
    }
}
impl SceneBuilder {
    pub fn provisional(source: SourceOwner, generation: u64, limits: Limits) -> Result<Self> {
        let limits = limits.effective();
        if source.len() > limits.source_bytes { return Err(limit(LimitKind::SourceBytes)); }
        let live = source.capacity();
        if live > limits.reserved_bytes { return Err(limit(LimitKind::ReservedBytes)); }
        let owner = crate::builder::NEXT_OWNER
            .try_update(Ordering::Relaxed, Ordering::Relaxed, |v| v.checked_add(1))
            .map_err(|_| arithmetic())?;
        let mut value = Self {
            owner, source, generation, scenes: Vec::new(), animation: AnimationStorage::Pending,
            initialization: DecodeInitialization::Unresolved,
            ignored: [Ignored::default(); 4],
            stats: MemoryStats { source_bytes: live, live_bytes: live,
                peak_live_bytes: live, ..Default::default() },
            limits, drafts: [None; 64], draft_depth: 0, request: None,
            text_commands: 0, next_serial: 1,
            root: SceneId { owner, slot: 0, serial: 1 },
        };
        let root = value.reserve_scene()?;
        value.scenes.push(SceneData::new(root.serial, None));
        value.root = root;
        Ok(value)
    }
    pub fn initialization(&self) -> DecodeInitialization { self.initialization }
    pub fn generation(&self) -> u64 { self.generation }
    pub(crate) fn require_finalized(&self) -> Result<()> {
        if self.initialization != DecodeInitialization::Finalized || self.animation.parsed().is_none() {
            return Err(invalid(0));
        }
        Ok(())
    }
    pub fn traversal_scene(&self, id: SceneId) -> Result<TraversalView<'_>> {
        let i = self.index(id)?;
        Ok(self.scenes[i].view(self.owner, i, &self.scenes, &self.source,
            self.animation.parsed().map(OwnedAnimation::view), self.scenes[i].viewport,
            self.ignored))
    }
    fn root_witness(&self, source: &DecodeSource<'_>, root: ElementId,
        control: &mut dyn WorkControl) -> Result<()> {
        control.checkpoint().map_err(stopped)?;
        if self.initialization != DecodeInitialization::Unresolved
            || !std::sync::Arc::ptr_eq(&self.source, source.source_owner()) {
            return Err(invalid(0));
        }
        let element = source.element(root, add(root.0, 1)?, control)?;
        let token = &element.tokens()[root.0];
        if token.depth != 0 || token.local_name.slice(&self.source) != Some(b"svg") {
            return Err(invalid(token.name.offset));
        }
        Ok(())
    }
    // Guard the hidden bypass with the canonical CSS engine, including original
    // invalid-display priority. This is a root query, never a second source parse.
    fn root_display(&self, source: &mut DecodeSource<'_>, root: ElementId,
        control: &mut dyn WorkControl) -> Result<bool> {
        self.root_witness(source, root, control)?;
        let style = source.compute_style(root, None, control)?;
        let Some(value) = style.value(vexel_svg_css::Property::Display) else { return Ok(false) };
        if style.keyword_equals(vexel_svg_css::Property::Display, b"none") { return Ok(true); }
        if [b"inline".as_slice(), b"block", b"contents"].iter()
            .any(|word| style.keyword_equals(vexel_svg_css::Property::Display, word)) {
