}
impl RasterComposition<'_> {
    pub fn stats(&self) -> RenderMemoryStats {
        self.job.stats()
    }
    pub fn work(&self) -> RenderWorkStats {
        self.job.work()
    }
    pub fn charge_work(
        &mut self,
        kind: WorkKind,
        units: u64,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let (_, _, work, _) = self.job.composition_parts();
        JobWorkMeter {
            work,
            inner: control,
        }
        .charge(kind, units)
        .map_err(stopped)
